impl crate::Read for GroupShapeContent {
    fn other(node: Node) -> Option<Self> {
        Some(Self::Other(node))
    }

    fn read(element: &Element) -> Self {
        match crate::name(element) {
            Some((NS_A, "cxnSp")) => Self::ConnectionShape(crate::read(element)),
            Some((NS_A14, "contentPart")) => Self::ContentPart(crate::read(element)),
            Some((NS_A, "graphicFrame")) => Self::GraphicFrame(crate::read(element)),
            Some((NS_A, "grpSp")) => Self::GroupShape(crate::read(element)),
            Some((NS_A, "pic")) => Self::Picture(crate::read(element)),
            Some((NS_A, "sp")) => Self::Shape(crate::read(element)),
            Some((NS_A, "txSp")) => Self::TextShape(crate::read(element)),
            _ => Self::Other(Node::Element(element.clone())),
        }
    }
}

impl crate::Write for GroupShapeContent {
    fn write_into(&self, writer: &mut crate::Writer<'_, '_>) {
        match self {
            Self::ConnectionShape(arm) => arm.write_into(writer),
            Self::ContentPart(arm) => arm.write_into(writer),
            Self::GraphicFrame(arm) => arm.write_into(writer),
            Self::GroupShape(arm) => arm.write_into(writer),
            Self::Other(node) => writer.other(node.clone()),
            Self::Picture(arm) => arm.write_into(writer),
            Self::Shape(arm) => arm.write_into(writer),
            Self::TextShape(arm) => arm.write_into(writer),
        }
    }
}

